// ─── File: MaintDemo.java ───
// Simulates DELETE (surgical, rollback), TRUNCATE (fast wipe, reset id), DROP (destroy).
package com.bank.maint;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class MaintDemo {
    private static final Logger log = Logger.getLogger(MaintDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TableMaintenanceService service = new TableMaintenanceService();
        SimTable txns = service.freshTxns();

        log.info(() -> "Start: rows=" + txns.rowCount() + " nextId=" + txns.nextId());

        log.info("=== DELETE WHERE txn_id=2 (inside txn, then ROLLBACK) ===");
        service.deleteRowWithRollback(txns, 2);
        log.info(() -> "After DELETE+ROLLBACK: rows=" + txns.rowCount()
            + " nextId=" + txns.nextId() + " (row restored, id unchanged)");

        log.info("=== TRUNCATE (fast wipe, reset identity) ===");
        service.truncate(txns);
        log.info(() -> "After TRUNCATE: rows=" + txns.rowCount()
            + " nextId=" + txns.nextId() + " (empty, id reset to 1)");

        log.info("=== DROP (destroy the table object) ===");
        SimTable legacy = service.freshTxns();
        service.drop(legacy);
        log.severe(() -> "After DROP: table exists=" + legacy.exists()
            + " (structure gone, cannot query)");
    }
}

// ─── Would be in model/SimTable.java ───
class SimTable {
    private final List<Map<String, Object>> rows = new ArrayList<>();
    private int nextId = 1;
    private boolean exists = true;

    int insert(String accountId, BigDecimal amount) {
        int id = nextId++;
        rows.add(new LinkedHashMap<>(Map.of("txn_id", id, "account_id", accountId, "amount", amount)));
        return id;
    }
    void deleteById(int id) { rows.removeIf(r -> r.get("txn_id").equals(id)); } // logged per row
    List<Map<String, Object>> snapshot() { return new ArrayList<>(rows); }      // for rollback
    void restore(List<Map<String, Object>> snap) { rows.clear(); rows.addAll(snap); }
    void truncate() { rows.clear(); nextId = 1; }   // fast wipe + identity reset
    void drop() { rows.clear(); exists = false; }   // destroy structure too
    int rowCount() { return rows.size(); }
    int nextId() { return nextId; }
    boolean exists() { return exists; }
}

// ─── Would be in service/TableMaintenanceService.java ───
class TableMaintenanceService {
    private static final Logger log = Logger.getLogger(TableMaintenanceService.class.getName());

    SimTable freshTxns() {
        SimTable t = new SimTable();
        t.insert("SAV2001", new BigDecimal("40000"));
        t.insert("SAV2001", new BigDecimal("10000"));
        t.insert("CUR3001", new BigDecimal("25000"));
        return t;
    }

    // DELETE is transactional and logged → can roll back.
    void deleteRowWithRollback(SimTable t, int id) {
        List<Map<String, Object>> before = t.snapshot(); // the transaction log / savepoint
        t.deleteById(id);
        log.fine(() -> "deleted id=" + id + ", rows now=" + t.rowCount());
        t.restore(before);                                // ROLLBACK restores the row
        log.info("ROLLBACK applied — deleted row restored");
    }

    // TRUNCATE empties fast and resets identity; treat as non-recoverable on some engines.
    void truncate(SimTable t) { t.truncate(); }

    // DROP removes the table object entirely.
    void drop(SimTable t) { t.drop(); }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
